   "code": "// logic.ts — pure functions: same input, same output, never mutate\nimport type { CheckIn, Habit, HabitId } from '../m01/types'\n\nexport function toggleCheckIn(list: CheckIn[], habitId: HabitId, day: string): CheckIn[] {\n  const exists = list.some((c) => c.habitId === habitId && c.day === day)\n  return exists\n    ? list.filter((c) => !(c.habitId === habitId && c.day === day)) // new array without it\n    : [...list, { habitId, day }] // new array with it\n}\n\nexport function countInWeek(list: CheckIn[], habitId: HabitId, weekDays: string[]): number {\n  return list.filter((c) => c.habitId === habitId && weekDays.includes(c.day)).length\n}\n\nexport function renameHabit(habits: Habit[], id: HabitId, name: string): Habit[] {\n  return habits.map((h) => (h.id === id ? { ...h, name } : h)) // copy only the changed object\n}"
