   "code": "import { useEffect, useState } from 'react'\n\n// useLocalStorage — state that survives F5. Read once (lazy initialiser), write in an effect.\nexport function useLocalStorage<T>(key: string, initial: T) {\n  const [value, setValue] = useState<T>(() => {\n    try {\n      const raw = localStorage.getItem(key)\n      return raw === null ? initial : (JSON.parse(raw) as T)\n    } catch {\n      return initial // corrupted JSON or storage blocked (private mode)\n    }\n  })\n  useEffect(() => {\n    try { localStorage.setItem(key, JSON.stringify(value)) } catch { /* quota full: keep working in memory */ }\n  }, [key, value])\n  return [value, setValue] as const\n}\n\n// useDebounce — the search box updates instantly, the expensive filter waits for a pause\nexport function useDebounce<T>(value: T, ms = 300): T {\n  const [debounced, setDebounced] = useState(value)\n  useEffect(() => {\n    const id = setTimeout(() => setDebounced(value), ms)\n    return () => clearTimeout(id) // cleanup: a new keystroke cancels the old timer\n  }, [value, ms])\n  return debounced\n}\n\n// useDocumentTitle — sync with something outside React, and put it back on unmount\nexport function useDocumentTitle(title: string) {\n  useEffect(() => {\n    const before = document.title\n    document.title = title\n    return () => { document.title = before }\n  }, [title])\n}"
