   "code": "import { create } from 'zustand'\nimport { persist } from 'zustand/middleware'\nimport { HABITS } from '../m01/seed'\nimport type { CheckIn, Habit } from '../m01/types'\nimport { toggleCheckIn } from '../m02/logic'\n\ninterface HabitState {\n  habits: Habit[]\n  checkIns: CheckIn[]\n  add: (h: Omit<Habit, 'id' | 'archived'>) => void\n  toggle: (habitId: string, day: string) => void\n  archive: (habitId: string) => void\n}\n\n// client state shared by many screens: one store, actions next to the data, persisted\nexport const useHabitStore = create<HabitState>()(\n  persist(\n    (set) => ({\n      habits: HABITS,\n      checkIns: [],\n      add: (h) => set((s) => ({ habits: [...s.habits, { ...h, id: crypto.randomUUID(), archived: false }] })),\n      toggle: (habitId, day) => set((s) => ({ checkIns: toggleCheckIn(s.checkIns, habitId, day) })),\n      archive: (habitId) => set((s) => ({ habits: s.habits.map((h) => (h.id === habitId ? { ...h, archived: true } : h)) })),\n    }),\n    { name: 'habit-store', version: 1 },\n  ),\n)\n\n// selectors: a component re-renders only when ITS slice changes\nexport const useActiveHabits = () => useHabitStore((s) => s.habits) // filter in the component, not here (new array = re-render loop)\nexport const useDoneToday = (day: string) => useHabitStore((s) => s.checkIns.filter((c) => c.day === day).length)"
