   "code": "import { useSearchParams } from 'react-router'\nimport { useActiveHabits } from './store'\n\n// the URL is the state of the filter: survives F5, can be shared as a link, Back works\nexport function FilteredHabits() {\n  const [params, setParams] = useSearchParams()\n  const q = params.get('q') ?? ''\n  const show = params.get('show') === 'archived' ? 'archived' : 'active'\n  const habits = useActiveHabits().filter((h) => (show === 'archived') === h.archived && h.name.toLowerCase().includes(q.toLowerCase()))\n\n  const update = (key: string, value: string) =>\n    setParams((p) => { if (value) p.set(key, value); else p.delete(key); return p }, { replace: key === 'q' })\n\n  return (\n    <section>\n      <input aria-label=\"Search\" value={q} onChange={(e) => update('q', e.target.value)} />\n      <select aria-label=\"Show\" value={show} onChange={(e) => update('show', e.target.value === 'active' ? '' : e.target.value)}>\n        <option value=\"active\">Active</option>\n        <option value=\"archived\">Archived</option>\n      </select>\n      <ul>{habits.map((h) => <li key={h.id}>{h.name}</li>)}</ul>\n    </section>\n  )\n}"
