   "code": "import type { Habit } from '../m01/types'\n\nexport class ApiError extends Error {\n  status: number\n  constructor(status: number, message: string) { super(message); this.status = status }\n}\n\nasync function request<T>(path: string, init: RequestInit = {}): Promise<T> {\n  const res = await fetch('/api' + path, { headers: { 'Content-Type': 'application/json' }, ...init })\n  if (!res.ok) throw new ApiError(res.status, (await res.json().catch(() => null))?.message ?? res.statusText)\n  return res.json() as Promise<T>\n}\n\nexport const api = {\n  habits: (signal?: AbortSignal) => request<Habit[]>('/habits', { signal }), // TanStack Query passes a signal ⇒ cancelled when unused\n  archive: (id: string) => request<Habit>('/habits/' + id, { method: 'PATCH', body: JSON.stringify({ archived: true }) }),\n}"
