   "code": "import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'\nimport type { Habit } from '../m01/types'\nimport { api } from './api'\n\nexport const habitKeys = { all: ['habits'] as const } // one place for query keys\n\nexport const useHabits = () =>\n  useQuery({ queryKey: habitKeys.all, queryFn: ({ signal }) => api.habits(signal), staleTime: 30_000 })\n\n// optimistic update: change the cache first, roll back if the server says no\nexport function useArchiveHabit() {\n  const qc = useQueryClient()\n  return useMutation({\n    mutationFn: api.archive,\n    onMutate: async (id: string) => {\n      await qc.cancelQueries({ queryKey: habitKeys.all })\n      const previous = qc.getQueryData<Habit[]>(habitKeys.all)\n      qc.setQueryData<Habit[]>(habitKeys.all, (old = []) => old.filter((h) => h.id !== id))\n      return { previous }\n    },\n    onError: (_err, _id, ctx) => qc.setQueryData(habitKeys.all, ctx?.previous),\n    onSettled: () => qc.invalidateQueries({ queryKey: habitKeys.all }),\n  })\n}"
