   "code": "import { Link, Navigate, NavLink, Outlet, useLocation, useParams, useRouteError, type RouteObject } from 'react-router'\nimport { HABITS } from '../m01/seed'\n\nconst auth = { user: null as null | { name: string } } // replaced by real auth in milestone 14\n\nfunction Layout() {\n  return (\n    <>\n      <nav aria-label=\"Main\"><NavLink to=\"/\">Today</NavLink> <NavLink to=\"/habits\">Habits</NavLink> <NavLink to=\"/stats\">Stats</NavLink></nav>\n      <main><Outlet /></main>\n    </>\n  )\n}\n\nfunction RequireLogin() {\n  const location = useLocation()\n  if (!auth.user) return <Navigate to={'/login?next=' + encodeURIComponent(location.pathname)} replace />\n  return <Outlet />\n}\n\nfunction HabitDetail() {\n  const { habitId } = useParams()\n  const habit = HABITS.find((h) => h.id === habitId)\n  if (!habit) return <NotFound /> // a wrong id in the URL is a normal case, not a crash\n  return <h1>{habit.emoji} {habit.name}</h1>\n}\n\nfunction NotFound() {\n  return <section><h1>Not found</h1><Link to=\"/\">Back to today</Link></section>\n}\n\nfunction RouteError() { // a component threw while rendering: keep the app alive, offer a way out\n  const err = useRouteError()\n  return <section role=\"alert\"><h1>Something went wrong</h1><p>{err instanceof Error ? err.message : 'Unknown error'}</p><Link to=\"/\">Back to today</Link></section>\n}\n\nexport const routes: RouteObject[] = [\n  {\n    element: <Layout />,\n    errorElement: <RouteError />,\n    children: [\n      { index: true, element: <h1>Today</h1> },\n      { path: 'habits', element: <h1>All habits</h1> },\n      { path: 'habits/:habitId', element: <HabitDetail /> },\n      { path: 'login', element: <h1>Log in</h1> },\n      { element: <RequireLogin />, children: [{ path: 'stats', element: <h1>Stats</h1> }] },\n      { path: '*', element: <NotFound /> },\n    ],\n  },\n]"
