   "code": "import { memo, useCallback, useState } from 'react'\nimport type { Habit } from '../m01/types'\n\nexport const renders = { count: 0 } // measurement only — remove after you wrote PERFORMANCE.md\n\ninterface RowProps { habit: Habit; done: boolean; onToggle: (id: string) => void }\n\nfunction Row({ habit, done, onToggle }: RowProps) {\n  renders.count++\n  return (\n    <li>\n      <button aria-pressed={done} onClick={() => onToggle(habit.id)}>{habit.name}</button>\n    </li>\n  )\n}\nconst MemoRow = memo(Row) // only worth it because the measurement below said so\n\nexport function HabitRows({ habits, useMemoRow }: { habits: Habit[]; useMemoRow: boolean }) {\n  const [done, setDone] = useState<Set<string>>(new Set())\n  // stable function identity, otherwise memo() compares a new prop every render and never skips\n  const onToggle = useCallback((id: string) => setDone((d) => { const n = new Set(d); if (n.has(id)) n.delete(id); else n.add(id); return n }), [])\n  const R = useMemoRow ? MemoRow : Row\n  return <ul>{habits.map((h) => <R key={h.id} habit={h} done={done.has(h.id)} onToggle={onToggle} />)}</ul>\n}"
