   "code": "import { QueryClient, QueryClientProvider } from '@tanstack/react-query'\nimport { renderHook, waitFor } from '@testing-library/react'\nimport { http, HttpResponse } from 'msw'\nimport { setupServer } from 'msw/node'\nimport type { ReactNode } from 'react'\nimport { afterAll, afterEach, beforeAll, describe, expect, test } from 'vitest'\nimport { streak, useStreak } from './streak'\n\ndescribe('streak() — the rule, edge cases first', () => {\n  test('counts back from today', () => expect(streak(['2026-11-20', '2026-11-21', '2026-11-22'], '2026-11-22')).toBe(3))\n  test('today not done yet keeps yesterday’s streak', () => expect(streak(['2026-11-20', '2026-11-21'], '2026-11-22')).toBe(2))\n  test('a gap breaks it', () => expect(streak(['2026-11-19', '2026-11-21', '2026-11-22'], '2026-11-22')).toBe(2))\n  test('crosses a month boundary', () => expect(streak(['2026-10-31', '2026-11-01'], '2026-11-01')).toBe(2))\n  test('empty', () => expect(streak([], '2026-11-22')).toBe(0))\n})\n\nconst server = setupServer(\n  http.get('*/api/habits/:id/check-ins', ({ params }) =>\n    params.id === 'h1' ? HttpResponse.json(['2026-11-21', '2026-11-22']) : new HttpResponse(null, { status: 404 })),\n)\nbeforeAll(() => server.listen({ onUnhandledRequest: 'error' }))\nafterEach(() => server.resetHandlers())\nafterAll(() => server.close())\n\nconst wrapper = ({ children }: { children: ReactNode }) => (\n  <QueryClientProvider client={new QueryClient({ defaultOptions: { queries: { retry: false } } })}>{children}</QueryClientProvider>\n)\n\ndescribe('useStreak() — the hook against a mocked network', () => {\n  test('success', async () => {\n    const { result } = renderHook(() => useStreak('h1', '2026-11-22'), { wrapper })\n    await waitFor(() => expect(result.current.isSuccess).toBe(true))\n    expect(result.current.data).toBe(2)\n  })\n  test('404 becomes an error state, not a crash', async () => {\n    const { result } = renderHook(() => useStreak('nope', '2026-11-22'), { wrapper })\n    await waitFor(() => expect(result.current.isError).toBe(true))\n    expect(result.current.error?.message).toBe('HTTP 404')\n  })\n})"
