   "file": "src/m10/story.test.tsx",
   "lang": "tsx",
   "code": "import { QueryClient, QueryClientProvider } from '@tanstack/react-query'\nimport { render, screen, within } from '@testing-library/react'\nimport userEvent from '@testing-library/user-event'\nimport { http, HttpResponse } from 'msw'\nimport { setupServer } from 'msw/node'\nimport { afterAll, beforeAll, expect, test } from 'vitest'\nimport { HABITS } from '../m01/seed'\nimport type { Habit } from '../m01/types'\nimport { HabitsPage } from '../m06/HabitsPage'\nimport { NewHabit } from './NewHabit'\n\nconst db: Habit[] = structuredClone(HABITS)\nconst server = setupServer(\n  http.get('*/api/habits', () => HttpResponse.json(db)),\n  http.post('*/api/habits', async ({ request }) => {\n    const body = (await request.json()) as Omit<Habit, 'id' | 'archived'>\n    if (db.some((h) => h.name.toLowerCase() === body.name.toLowerCase()))\n      return HttpResponse.json({ message: 'You already have a habit with this name' }, { status: 409 })\n    const habit = { ...body, id: 'h' + (db.length + 1), archived: false }\n    db.push(habit)\n    return HttpResponse.json(habit, { status: 201 })\n  }),\n)\nbeforeAll(() => server.listen({ onUnhandledRequest: 'error' }))\nafterAll(() => server.close())\n\ntest('story: add a habit, see it in the list; a duplicate name is refused at the field', async () => {\n  const user = userEvent.setup()\n  render(<QueryClientProvider client={new QueryClient()}><NewHabit /><HabitsPage /></QueryClientProvider>)\n  const list = await screen.findByRole('list')\n  expect(within(list).getAllByRole('listitem')).toHaveLength(3)\n\n  await user.type(screen.getByLabelText('New habit'), 'Drink 2 l of water{Enter}')\n  expect(await within(list).findByRole('button', { name: 'Archive Drink 2 l of water' })).toBeInTheDocument()\n  expect(screen.getByLabelText('New habit')).toHaveValue('') // form reset after success\n\n  await user.type(screen.getByLabelText('New habit'), 'run 3 KM{Enter}')\n  expect(await screen.findByText('You already have a habit with this name')).toBeInTheDocument()\n  expect(screen.getByLabelText('New habit')).toHaveFocus()\n  expect(screen.getByLabelText('New habit')).toHaveAttribute('aria-invalid', 'true')\n  expect(within(list).getAllByRole('listitem')).toHaveLength(4)\n})"
