   "code": "import { Component, type ErrorInfo, type ReactNode } from 'react'\n\ninterface Props { fallback: (reset: () => void) => ReactNode; children: ReactNode }\n\n// still a class in React 19: there is no hook for \"catch errors thrown while rendering children\"\nexport class ErrorBoundary extends Component<Props, { error: Error | null }> {\n  state = { error: null as Error | null }\n  static getDerivedStateFromError(error: Error) { return { error } }\n  componentDidCatch(error: Error, info: ErrorInfo) { console.warn('[report]', error.message, info.componentStack?.split('\\n')[1]?.trim()) }\n  reset = () => this.setState({ error: null })\n  render() { return this.state.error ? this.props.fallback(this.reset) : this.props.children }\n}"
