   "code": "import { render, screen } from '@testing-library/react'\nimport userEvent from '@testing-library/user-event'\nimport { useState } from 'react'\nimport { expect, test, vi } from 'vitest'\nimport { ErrorBoundary } from './ErrorBoundary'\nimport { Modal } from './Modal'\n\nfunction Screen() {\n  const [open, setOpen] = useState(false)\n  return (\n    <div style={{ overflow: 'hidden' }} data-testid=\"card\">\n      <button onClick={() => setOpen(true)}>Delete habit</button>\n      {open && <Modal title=\"Delete “Run 3 km”?\" onClose={() => setOpen(false)}><button>Confirm</button></Modal>}\n    </div>\n  )\n}\n\ntest('modal: lives in body, takes focus, Escape closes, focus goes back to the opener', async () => {\n  const user = userEvent.setup()\n  render(<Screen />)\n  await user.click(screen.getByRole('button', { name: 'Delete habit' }))\n  const dialog = screen.getByRole('dialog', { name: 'Delete “Run 3 km”?' })\n  expect(dialog.parentElement?.parentElement).toBe(document.body)\n  expect(screen.getByTestId('card')).not.toContainElement(dialog)\n  expect(dialog).toHaveFocus()\n  await user.keyboard('{Escape}')\n  expect(screen.queryByRole('dialog')).not.toBeInTheDocument()\n  expect(screen.getByRole('button', { name: 'Delete habit' })).toHaveFocus()\n})\n\nlet fail = true\nfunction StreakWidget() {\n  if (fail) throw new Error('streak service returned garbage')\n  return <p>Streak: 4 days</p>\n}\n\ntest('error boundary: one broken widget does not blank the page, and Retry recovers', async () => {\n  vi.spyOn(console, 'error').mockImplementation(() => {}) // React logs the caught error; keep output readable\n  const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})\n  render(\n    <main>\n      <h1>Today</h1>\n      <ErrorBoundary fallback={(reset) => <p role=\"alert\">Widget failed <button onClick={reset}>Retry</button></p>}>\n        <StreakWidget />\n      </ErrorBoundary>\n    </main>,\n  )\n  expect(screen.getByRole('heading', { name: 'Today' })).toBeInTheDocument()\n  expect(screen.getByRole('alert')).toHaveTextContent('Widget failed')\n  expect(warn.mock.calls[0].slice(0, 2)).toEqual(['[report]', 'streak service returned garbage'])\n  fail = false\n  await userEvent.click(screen.getByRole('button', { name: 'Retry' }))\n  expect(screen.getByText('Streak: 4 days')).toBeInTheDocument()\n})\n\nfunction EditForm({ name }: { name: string }) {\n  const [draft, setDraft] = useState(name) // initial value is read ONCE per component identity\n  return <input aria-label=\"Draft\" value={draft} onChange={(e) => setDraft(e.target.value)} />\n}\n\ntest('key resets local state when the edited habit changes', () => {\n  const { rerender } = render(<EditForm key=\"h1\" name=\"Read 20 pages\" />)\n  rerender(<EditForm key=\"h1\" name=\"Run 3 km\" />)\n  expect(screen.getByLabelText('Draft')).toHaveValue('Read 20 pages') // same key: stale draft — the bug\n  rerender(<EditForm key=\"h2\" name=\"Run 3 km\" />)\n  expect(screen.getByLabelText('Draft')).toHaveValue('Run 3 km') // new key: fresh component\n})"
