   "lang": "tsx",
   "code": "import { useActionState, useDeferredValue, useOptimistic, useState } from 'react'\n\ninterface Item { name: string; pending?: boolean }\ntype Save = (name: string) => Promise<void>\n\n// React 19 Actions: the form owns pending/error state; useOptimistic shows the row before the server answers\nexport function QuickAdd({ save, initial }: { save: Save; initial: Item[] }) {\n  const [items, setItems] = useState(initial)\n  const [optimistic, addOptimistic] = useOptimistic(items, (cur, name: string) => [...cur, { name, pending: true }])\n  const [error, submit, isPending] = useActionState(async (_prev: string | null, form: FormData) => {\n    const name = String(form.get('name') ?? '').trim()\n    if (name.length < 2) return 'At least 2 characters'\n    addOptimistic(name)\n    try {\n      await save(name)\n      setItems((cur) => [...cur, { name }])\n      return null\n    } catch {\n      return 'Could not save “' + name + '”' // the optimistic row disappears by itself when the action ends\n    }\n  }, null)\n\n  const [query, setQuery] = useState('')\n  const deferred = useDeferredValue(query) // typing stays urgent; the (possibly long) filtered list can lag behind\n  const shown = optimistic.filter((i) => i.name.toLowerCase().includes(deferred.toLowerCase()))\n\n  return (\n    <>\n      <form action={submit}>\n        <input name=\"name\" aria-label=\"Quick add\" />\n        <button disabled={isPending}>Add</button>\n        {error && <p role=\"alert\">{error}</p>}\n      </form>\n      <input aria-label=\"Filter\" value={query} onChange={(e) => setQuery(e.target.value)} />\n      <ul>{shown.map((i) => <li key={i.name} style={{ opacity: i.pending ? 0.5 : 1 }}>{i.name}{i.pending && ' (saving…)'}</li>)}</ul>\n    </>\n  )\n}"
