   "code": "import { render, screen } from '@testing-library/react'\nimport userEvent from '@testing-library/user-event'\nimport { expect, test } from 'vitest'\nimport { QuickAdd } from './QuickAdd'\n\nfunction deferredSave() {\n  let finish!: (ok: boolean) => void\n  const save = () => new Promise<void>((ok, fail) => { finish = (good) => (good ? ok() : fail(new Error('500'))) })\n  return { save, finish: (good: boolean) => finish(good) }\n}\n\ntest('the row appears at once as \"saving…\", then becomes real', async () => {\n  const user = userEvent.setup()\n  const s = deferredSave()\n  render(<QuickAdd save={s.save} initial={[{ name: 'Read 20 pages' }]} />)\n  await user.type(screen.getByLabelText('Quick add'), 'Stretch 5 min{Enter}')\n  expect(await screen.findByText('Stretch 5 min (saving…)')).toBeInTheDocument()\n  expect(screen.getByRole('button', { name: 'Add' })).toBeDisabled()\n  s.finish(true)\n  expect(await screen.findByText('Stretch 5 min')).toBeInTheDocument()\n  expect(screen.queryByText(/saving/)).not.toBeInTheDocument()\n})\n\ntest('when the server fails the optimistic row vanishes and the error is shown', async () => {\n  const user = userEvent.setup()\n  const s = deferredSave()\n  render(<QuickAdd save={s.save} initial={[]} />)\n  await user.type(screen.getByLabelText('Quick add'), 'Meditate{Enter}')\n  expect(await screen.findByText('Meditate (saving…)')).toBeInTheDocument()\n  s.finish(false)\n  expect(await screen.findByRole('alert')).toHaveTextContent('Could not save “Meditate”')\n  expect(screen.queryByText(/Meditate/, { selector: 'li' })).not.toBeInTheDocument()\n})"
