   "code": "import { render, screen } from '@testing-library/react'\nimport userEvent from '@testing-library/user-event'\nimport { expect, test } from 'vitest'\nimport { fmt, safeNote } from './safe'\nimport Tabs from './Tabs'\n\ntest('Tabs: one API, keyboard works like a native tab widget', async () => {\n  const user = userEvent.setup()\n  render(\n    <Tabs defaultValue=\"week\">\n      <Tabs.List label=\"Period\"><Tabs.Tab value=\"week\">Week</Tabs.Tab><Tabs.Tab value=\"month\">Month</Tabs.Tab><Tabs.Tab value=\"year\">Year</Tabs.Tab></Tabs.List>\n      <Tabs.Panel value=\"week\">7 days</Tabs.Panel><Tabs.Panel value=\"month\">30 days</Tabs.Panel><Tabs.Panel value=\"year\">365 days</Tabs.Panel>\n    </Tabs>,\n  )\n  await user.tab()\n  expect(screen.getByRole('tab', { name: 'Week' })).toHaveFocus()\n  await user.keyboard('{ArrowRight}')\n  expect(screen.getByRole('tab', { name: 'Month' })).toHaveAttribute('aria-selected', 'true')\n  expect(screen.getByRole('tabpanel', { name: 'Month' })).toHaveTextContent('30 days')\n  await user.keyboard('{ArrowLeft}{ArrowLeft}')\n  expect(screen.getByRole('tab', { name: 'Year' })).toHaveFocus() // wraps around\n})\n\ntest('safeNote keeps formatting, drops scripts and handlers', () => {\n  const dirty = '<b>Ran</b> 3 km <img src=x onerror=\"alert(1)\"><script>steal()</script><a href=\"javascript:alert(1)\">link</a>'\n  console.log(safeNote(dirty))\n  expect(safeNote(dirty)).toBe('<b>Ran</b> 3 km <a>link</a>')\n})\n\ntest('Intl formats the same data for two locales', () => {\n  for (const l of ['vi-VN', 'en-US'] as const) {\n    const f = fmt(l)\n    console.log(l.padEnd(6), '|', f.money(1500000), '|', f.day('2026-11-22T03:00:00Z'), '|', f.percent(0.857))\n  }\n  expect(fmt('vi-VN').percent(0.857)).toBe('86%')\n})"
