   "file": "src/m14/apiClient.test.ts",
   "lang": "ts",
   "code": "import { http, HttpResponse, delay } from 'msw'\nimport { setupServer } from 'msw/node'\nimport { afterAll, beforeAll, beforeEach, expect, test, vi } from 'vitest'\nimport { apiFetch, session } from './apiClient'\n\nlet refreshCalls = 0\nlet refreshWorks = true\nconst keys: string[] = []\nconst server = setupServer(\n  http.post('*/api/auth/refresh', async () => {\n    refreshCalls++\n    await delay(20)\n    return refreshWorks ? HttpResponse.json({ accessToken: 'fresh' }) : new HttpResponse(null, { status: 401 })\n  }),\n  http.all('*/api/habits*', ({ request }) => {\n    if (request.method === 'POST') keys.push(request.headers.get('Idempotency-Key') ?? '-')\n    return request.headers.get('Authorization') === 'Bearer fresh' ? HttpResponse.json({ ok: true }) : new HttpResponse(null, { status: 401 })\n  }),\n  http.get('*/api/slow', async () => { await delay(500); return HttpResponse.json({}) }),\n)\nbeforeAll(() => server.listen({ onUnhandledRequest: 'error' }))\nafterAll(() => server.close())\nbeforeEach(() => { refreshCalls = 0; refreshWorks = true; keys.length = 0; session.set('expired') })\n\ntest('five parallel 401s ⇒ ONE refresh, all five succeed', async () => {\n  const results = await Promise.all(Array.from({ length: 5 }, () => apiFetch('/habits')))\n  console.log('requests:', results.length, '· refresh calls:', refreshCalls)\n  expect(refreshCalls).toBe(1)\n  expect(results.every((r) => (r as { ok: boolean }).ok)).toBe(true)\n})\n\ntest('the retried POST keeps its Idempotency-Key (server can dedupe)', async () => {\n  await apiFetch('/habits', { method: 'POST', body: '{}' })\n  console.log('keys seen by server:', keys.length, '· identical:', keys[0] === keys[1])\n  expect(keys).toHaveLength(2)\n  expect(keys[0]).toBe(keys[1])\n})\n\ntest('refresh refused ⇒ logout once, no infinite loop', async () => {\n  refreshWorks = false\n  session.onLogout = vi.fn()\n  await expect(apiFetch('/habits')).rejects.toThrow('Session expired')\n  expect(session.onLogout).toHaveBeenCalledTimes(1)\n  expect(refreshCalls).toBe(1)\n})\n\ntest('a hung server is cut by the timeout', async () => {\n  await expect(apiFetch('/slow', { timeoutMs: 100 })).rejects.toThrow(/timed out|aborted|timeout/i)\n})"
